import Link from \"next/link\";
import { revalidatePath } from \"next/cache\";
import { addBook, listBooks, markBookFinished } from \"../lib/books\";

export const dynamic = \"force-dynamic\";

async function addBookAction(formData) {
  \"use server\";

  const title = formData.get(\"title\")?.toString().trim();
  const author = formData.get(\"author\")?.toString().trim();
  const notes = formData.get(\"notes\")?.toString().trim() ?? \"\";

  if ("'!title || !author) {
    return;
  }

  await addBook({ title, author, notes });
  revalidatePath("/");
}

async function markFinishedAction(formData) {
  "use server";

  const id = formData.get("id")?.toString();

  if (!id) {
    return;
  }

  await markBookFinished(id);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

function sortByDateDesc(books, dateKey) {
  return [...books].sort((first, second) => {
    const firstTime = first[dateKey] ? new Date(first[dateKey]).getTime() : 0;
    const secondTime = second[dateKey] ? new Date(second[dateKey]).getTime() : 0;
    return secondTime - firstTime;
  });
}

function BookList({ books, showFinishButton }) {
  if (!books.length) {
    return <p className="empty-copy">No books here yet.</p>;
  }

  return (
    <ul className="book-list">
      {books.map((book) => (
        <li key={book.id} className="book-row">
          <div>
            <Link href={`/books/${book.id}`} className="book-link">
              {book.title}
            </Link>
            <p className="book-meta">by {book.author}</p>
          </div>

          {showFinishButton ? (
            <form action={markFinishedAction}>
              <input type="hidden" name="id" value={book.id} />
              <button type="submit" className="secondary-button">
                Mark finished
              </button>
            </form>
          ) : (
            <span className="status-pill">Finished</span>
          )}
        </li>
      ))}
    </ul>
  );
}

export default async function HomePage() {
  const books = await listBooks();
  const currentlyReading = sortByDateDesc(
    books.filter((book) => book.status === "reading"),
    "createdAt",
  );
  const finishedBooks = sortByDateDesc(
    books.filter((book) => book.status === "finished"),
    "finishedAt",
  );

  return (
    <div className="stack">
      <header>
        <h1>Reading Tracker</h1>
        <p className="subhead">Track what you are reading and what you have finished.</p>
      </header>

      <section className="card">
        <h2>Add a Book</h2>
        <form action={addBookAction} className="book-form">
          <label>
            Title
            <input name="title" required />
          </label>

          <label>
            Author
            <input name="author" required />
          </label>

          <label>
            Notes
            <textarea name="notes" rows={4} placeholder="Optional notes" />
          </label>

          <button type="submit">Add book</button>
        </form>
      </section>

      <section className="card">
        <h2>Currently Reading</h2>
        <BookList books={currentlyReading} showFinishButton />
      </section>

      <section className="card">
        <h2>Finished</h2>
        <BookList books={finishedBooks} showFinishButton={false} />
      </section>
    </div>
  );
}
EOF

